-- Update default admin password to md5('admin') and set theme to algopanel
UPDATE dbispconfig.sys_user SET passwort = MD5('admin'), app_theme = 'algopanel' WHERE username = 'admin';
ALTER TABLE dbispconfig.sys_user ALTER COLUMN app_theme SET DEFAULT 'algopanel';

-- Ensure ispconfig user has full access
GRANT ALL PRIVILEGES ON dbispconfig.* TO 'ispconfig'@'%' IDENTIFIED BY 'ispconfig_password';
FLUSH PRIVILEGES;
ALTER TABLE dbispconfig.sys_ini MODIFY default_logo MEDIUMTEXT, MODIFY custom_logo MEDIUMTEXT;
UPDATE dbispconfig.sys_ini SET default_logo = "data:image/png;base64,", custom_logo = "data:image/png;base64," WHERE sysini_id = 1;
